import * as Dialog from '@radix-ui/react-dialog';
import {mountProbe,useProbe,Overlay} from './common';
import type {ApplicationSDK} from '@ksf/sdk';
function App(){const p=useProbe();return <main className="probe" data-library="Radix UI"><h1>Radix UI 独立应用</h1><p>应用自行打包 React 与 Radix Dialog。</p><input aria-label="Radix 草稿" value={p.draft} onChange={e=>p.setDraft(e.target.value)}/><Dialog.Root modal={false} open={p.open} onOpenChange={p.setOpen}><Dialog.Trigger ref={p.trigger} className="probe-button">打开 Radix 弹层</Dialog.Trigger><Overlay appId={p.sdk.appId}><Dialog.Content ref={p.panel} className="probe-panel" onOpenAutoFocus={e=>e.preventDefault()} onCloseAutoFocus={e=>{e.preventDefault();if(p.sdk.getSnapshot().active)p.trigger.current?.focus({preventScroll:true});}} onEscapeKeyDown={e=>e.preventDefault()} onInteractOutside={e=>e.preventDefault()}><Dialog.Title>Radix 应用内弹层</Dialog.Title><Dialog.Description>仅属于 Radix 窗口；其他应用仍可操作。</Dialog.Description><input aria-label="Radix 弹层输入"/><Dialog.Close>关闭 Radix 弹层</Dialog.Close></Dialog.Content></Overlay></Dialog.Root></main>}
export function mount(container:HTMLElement,sdk:ApplicationSDK){return mountProbe(App,container,sdk)}
